138	  /// state (including a fast resolve before the 300ms threshold, RNF01)
139	  /// cancels it and resets [_showSearchSkeleton].
140	  void _onSearchStateChanged(
141	    BuildContext context,
142	    Resource<List<Entry>> state,
143	  ) {
144	    _searchSkeletonTimer?.cancel();
145	    if (state is ResourceLoading<List<Entry>>) {
146	      _searchSkeletonTimer = Timer(_skeletonThreshold, () {
147	        if (mounted) {
148	          setState(() => _showSearchSkeleton = true);
149	        }
150	      });
151	      return;
152	    }
153	    if (_showSearchSkeleton) {
154	      setState(() => _showSearchSkeleton = false);
155	    }
156	  }
