89	  /// spec-5-3 — `EntriesFilterSheet`'s "Aplicar", `_ActiveFiltersRow`'s
90	  /// chip-remove ×2, and "Limpar filtros", all via `MeusRegistrosScreen`'s
91	  /// own bridge (Design Notes) — called right alongside the existing
92	  /// `MeusRegistrosCubit.applyFilters()`/`clearFilters()` call, never in
93	  /// place of it. Also called unconditionally from `MeusRegistrosScreen.
94	  /// initState()` on every mount (Boundaries: "no stale filter carried
95	  /// forward"). Always stores [source]/[dateFrom]/[dateTo] regardless of
96	  /// whether a search is active (Boundaries: "always stores the fields").
97	  ///
98	  /// Only when [_lastQuery] is non-empty — a search is actually active —
99	  /// *and* at least one of [source]/[dateFrom]/[dateTo] actually differs
100	  /// from what was already stored (review finding: skips a wasted
101	  /// `entries-search` network call when `initState()`'s own unconditional
102	  /// reset finds nothing to actually reset) — does this cancel any pending
103	  /// debounce and immediately re-run [_search] with that same term and the
104	  /// just-stored filters (Boundaries: "no debounce on the filter-triggered
105	  /// re-search"); while idle, the new selection is simply kept for
106	  /// whenever the next query starts.
107	  void updateFilters({
108	    EntrySource? source,
109	    DateTime? dateFrom,
110	    DateTime? dateTo,
111	  }) {
112	    final filtersChanged =
113	        source != _activeSource ||
114	        dateFrom != _activeDateFrom ||
115	        dateTo != _activeDateTo;
116	    _activeSource = source;
117	    _activeDateFrom = dateFrom;
118	    _activeDateTo = dateTo;
119	    if (_lastQuery.isEmpty || !filtersChanged) {
120	      return;
121	    }
122	    // Review finding: `close()` can race this call too (e.g. `initState()`
123	    // now calls this unconditionally on every mount) — same `isClosed`
124	    // rationale `onQueryChanged`'s own guard above documents; `_search()`'s
125	    // first line is `emit(ResourceLoading())`, which would otherwise throw
126	    // after `close()`.
127	    if (isClosed) {
128	      return;
129	    }
130	    _debounceTimer?.cancel();
131	    _search(_lastQuery);
132	  }
133	
134	  Future<void> _search(String query) async {
135	    final generation = ++_generation;
136	    // Review finding: deliberately *not* `const` — `ResourceLoading<T>`
137	    // has no custom `==`, so `const ResourceLoading()` is a canonicalized
138	    // singleton instance. Two searches in a row (e.g. "an" still in
139	    // flight when "ans" debounces) would otherwise both emit that exact
140	    // same instance; `Cubit.emit` (package:bloc) skips re-emitting a state
141	    // `==` to the current one, so the second transition into loading
142	    // would silently no-op — `MeusRegistrosScreen._onSearchStateChanged`'s
143	    // listener never re-fires, and its 300ms skeleton timer never resets
144	    // for "ans", measuring RNF01's threshold from the wrong start time. A
145	    // fresh (non-const) instance is identity-distinct from the prior one
146	    // even though both are `ResourceLoading`, so `emit` always proceeds.
147	    emit(ResourceLoading());
148	    final result = await _repository.search(
149	      query,
150	      source: _activeSource,
151	      dateFrom: _activeDateFrom,
152	      dateTo: _activeDateTo,
153	    );
154	    // Mirrors `MeusRegistrosCubit.loadFirstPage`'s own guard: `close()` can
155	    // race this awaited call, and a newer query (or a clear back to idle)
156	    // can have superseded this one while it was in flight.
157	    if (isClosed || generation != _generation) {
158	      return;
159	    }
160	    result.match(
161	      (failure) => emit(ResourceError(failure)),
162	      (entries) => emit(ResourceData(entries)),
163	    );
164	  }
